                length=sizeof(gyro_l_search);
#endif
			break;
		case RT90SEARCH:
			setangle(90);
			turn_gyro=gyro_r_search;turn_vl=vouter_search;turn_vr=vinner_search;
			length=sizeof(gyro_r_search);	
			break;
		case POINTL90:
