void mazeSearch()				 
{	
	if(goaheadbugflag==1) goaheadbugflag=0; 
	eh=0;
	e=0;
	gangleh=0;
	ganglehh=0;
	peakgangle=0;
	peakgangleh=0;
	task=SMARTSTRAIGHT;
	 
	while(1){if(track>90 && track<180)sim_tick();
#ifdef MOUSE_REMOTE
		if (LP_AbortRequested()) break; 
#endif
		if(track>=180) 
		{	
			blocknum++; 
			 
			settrack(0);
			if(goaheadbugflag==0) __mouseCoorUpdate();
			if(breakornot()==1){blocknum=1;break;}
		}
		if(track>90 && track<180); 
		else
		{		  
			if(lefthaswall==1 || righthaswall==1) mazesearchhaswall(); 
			else if(lefthaswall==0 && righthaswall==0) mazesearchnowall();
		}
	}
}
u8 breakornot() 
{
	if(forwardhaswall==1)return 1;
	else if(lefthaswall==0)return 1;
	else if(righthaswall==0)return 1;
	else return 0;
}
void before90turn(u8 Direction)				 
{
 
 
 
		e=0;eh=0;
		task=BEFORE90TURN;
#ifndef MOUSE_REMOTE
        
        if(spurt_search_active==1 && spurt_exec_index==200)
        {
            while(track<turn_delay)
            {sim_tick();
                if(!spurtSearchRunning() || disf<10)
                {
                    spurt_search_failed=1;
                    return;
                }
            }
            turno=0;
            return;
        }
#endif
		while(1){sim_tick();
			if(spurt_search_active==1 && !spurtSearchRunning()) return;
 
		
			if(LastSearchAction==TURN180)					 
			{
				if(Direction==TurnLeft)						 
				{
					if(track>=turn_delay+27) 
					{
						turno=0; break;
					}
				}
				else
				{
					if(track>=turn_delay+20)						 
					{
						turno=0; break;
					}
				}
			} 
			
			
			if(LastSearchAction==Stright)					 
			{
				if(Direction==TurnLeft)						 
				{
					if(track>=turn_delay-2)
					{
						turno=0; break;
					}
				}
				else
				{
					if(track>=turn_delay-3)						 
					{
						turno=0; break;
					}
				}
			}
			else if(LastSearchAction==TurnLeft)
			{
				if(Direction==TurnLeft)						 
				{
					if(track>=turn_delay)
					{
						turno=0; break;
					}
				}
				else
				{
					if(track>=turn_delay-5)						  
					{
						turno=0; break;
					}
				}
			}
			else if(LastSearchAction==TurnRight)
			{
				if(Direction==TurnLeft)					 
				{
					if(track>=turn_delay-4)    
					{
						turno=0; break;
					}
				}
				else
				{
					if(track>=turn_delay-1)						 
					{
						turno=0; break;
					}
				}
			}
		}
 
}
